import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// issue #12: the customer discount applies once.
test('customer discount applies once: 1,000 at rate 0.1 is 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// 10 lines: customer discount first, then the 5% bulk discount once.
// 10,000 -> 9,000 -> 8,550
test('10 lines at rate 0.1: bulk discount applies once after the customer discount', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

// 9 lines is below the bulk threshold: 9,000 -> 8,100
test('9 lines at rate 0.1: no bulk discount', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

// Rate 0 keeps only the bulk discount: 10,000 -> 9,500
test('10 lines at rate 0: only the bulk discount', () => {
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(10, 1000)), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
